<?php
namespace App\Http\Controllers;
use App\Http\Requests\MedicineRequest; use App\Models\Medicine; use Illuminate\Http\Request;
class MedicineController extends Controller { public function index(Request $request) { $search=trim((string)$request->query('search','')); $medicines=Medicine::query()->when($search,fn($query)=>$query->where(fn($q)=>$q->where('brand_name','like',"%{$search}%")->orWhere('category','like',"%{$search}%")))->orderBy('brand_name')->get(); return response()->json(['data'=>$medicines]); } public function store(MedicineRequest $request) { $medicine=Medicine::create($request->validated()); return response()->json(['message'=>'Medicine created successfully.','data'=>$medicine],201); } public function show(Medicine $medicine) { return response()->json(['data'=>$medicine]); } public function update(MedicineRequest $request, Medicine $medicine) { $medicine->update($request->validated()); return response()->json(['message'=>'Medicine updated successfully.','data'=>$medicine->fresh()]); } public function destroy(Medicine $medicine) { $medicine->delete(); return response()->json(['message'=>'Medicine deleted successfully.']); } }